<?php
namespace App\Services;use App\Models\{CommitteeMeeting,CommitteeMinute,Documento,DocumentoCambio};use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Support\Facades\Storage;use Illuminate\Validation\ValidationException;
class CommitteeMinuteService{public function __construct(private CommitteeOperationService $operations){}public function generate(CommitteeMeeting $meeting,int $userId):CommitteeMinute{if(!in_array($meeting->status,['minutes_draft','minutes_review','closed']))throw ValidationException::withMessages(['meeting'=>'La reunión aún no está lista para generar acta.']);$version=($meeting->minutes()->max('version')??0)+1;$number=$meeting->committee->type->value.'-'.$meeting->meeting_date->year.'-'.str_pad($meeting->id,3,'0',STR_PAD_LEFT);$minute=$meeting->minutes()->create(['minute_number'=>$number,'status'=>'draft','version'=>$version,'generated_by'=>$userId,'generated_at'=>now()]);$this->writePdf($minute);$this->operations->audit($meeting->committee,'minute_generated',$minute,$userId,['version'=>$version]);return$minute;}public function approve(CommitteeMinute $minute,int $userId,string $observations=''):void{abort_if($minute->status!=='draft',422,'Solo un borrador puede enviarse a revisión.');$minute->update(['status'=>'approved','approved_by'=>$userId,'approved_at'=>now(),'observations'=>$observations]);$minute->meeting->update(['status'=>'minutes_review']);$this->operations->audit($minute->meeting->committee,'minute_approved',$minute,$userId);}public function finalize(CommitteeMinute $minute,int $userId):void{abort_if($minute->status!=='approved',422,'El acta debe estar aprobada antes de finalizar.');$content=Storage::disk('public')->get($minute->document_path);$number=(Documento::max('id')??0)+1;$document=Documento::create(['titulo'=>'Acta '.$minute->minute_number,'descripcion'=>'Acta de reunión de comité','categoria'=>'Formatos y Registros','archivo_ruta'=>$minute->document_path,'extension_archivo'=>'pdf','subido_por'=>$userId,'codigo'=>'SST-F-'.str_pad($number,2,'0',STR_PAD_LEFT),'nombre_archivo'=>basename($minute->document_path),'fecha_vigencia_inicio'=>$minute->meeting->meeting_date,'version'=>(string)$minute->version,'tipo_accion'=>$minute->version===1?'Nuevo':'Modificacion']);DocumentoCambio::create(['documento_id'=>$document->id,'version'=>(string)$minute->version,'fecha_vigencia_inicio'=>$minute->meeting->meeting_date,'tipo_cambio'=>$minute->version===1?'Nuevo':'Modificacion','observaciones'=>'Acta finalizada','registrado_por'=>$userId]);$minute->update(['status'=>'final','documento_id'=>$document->id,'finalized_by'=>$userId,'finalized_at'=>now(),'document_hash'=>hash('sha256',$content)]);$minute->meeting->update(['status'=>'closed']);$this->operations->audit($minute->meeting->committee,'minute_finalized',$minute,$userId);}private function writePdf(CommitteeMinute $minute):void{$minute->load(['meeting.committee.company','meeting.period','meeting.president.employee','meeting.secretary.employee','meeting.attendees.member.employee','meeting.agendaItems','meeting.decisions','meeting.commitments.responsible']);$content=Pdf::loadView('pdf.committee_meeting_minute',compact('minute'))->output();$path="documentos/comites/actas/{$minute->minute_number}-v{$minute->version}.pdf";Storage::disk('public')->put($path,$content);$minute->update(['document_path'=>$path,'document_hash'=>hash('sha256',$content)]);}}
